#!/usr/bin/env python3
"""Apply the approved clarity pass to the fourteen bespoke light references.

Preserves the original Stitch markup, covers, and generated utility CSS. The
captured utility CSS and a small subset of the original Material Symbols font
are baked below so replay does not need a CDN. Run with the bundled lxml Python.
An already refined file is left unchanged; --source can replay original exports.
"""
import argparse
import base64
import json
import re
from urllib.parse import quote
from pathlib import Path
from lxml import html, etree

ROOT = Path(__file__).resolve().parents[1]
SLUGS = ['home', 'book-details', 'library', 'journal', 'explore', 'shelves',
         'welcome', 'guest-import', 'account-sync', 'settings', 'downloads',
         'sync-conflict', 'reader', 'reader-appearance']


def clean(e):
    return ' '.join(e.xpath('.//text()[not(ancestor::*[contains(@class,"material-symbols-outlined")])]').__iter__()).strip() if len(e) else (e.text or '').strip()


def label(e):
    return ' '.join(clean(e).split())


def remove(e):
    if e is not None and e.getparent() is not None:
        e.getparent().remove(e)


def find(t, value, tags='*'):
    return next((e for e in t.xpath('.//' + tags) if label(e) == value), None)


def direct(t, value):
    return next((e for e in t.iter() if (e.text or '').strip() == value), None)


def txt(e, value):
    for child in list(e):
        e.remove(child)
    e.text = value


def addclass(e, value):
    e.set('class', (e.get('class', '') + ' ' + value).strip())


def style(e, value):
    e.set('style', e.get('style', '').rstrip(';') + ';' + value)


def fragment(value):
    try:
        return html.fragment_fromstring(value)
    except etree.ParserError:
        return html.fragment_fromstring(value,create_parent="div")


def link(e, target):
    e.tag = 'a'
    for attr in ['type', 'role', 'tabindex', 'onclick', 'aria-checked', 'aria-pressed']:
        e.attrib.pop(attr, None)
    e.set('href', '../prototype.html#' + target)
    return e


def menu(button, entries):
    d = html.Element('details', {'class': 'clarity-menu'})
    s = etree.SubElement(d, 'summary', {'aria-label': button.get('aria-label', 'More actions'), 'class': 'clarity-icon'})
    s.append(fragment('<span class="material-symbols-outlined" aria-hidden="true">more_vert</span>'))
    box = etree.SubElement(d, 'div', {'class': 'clarity-menu-items'})
    for title, target in entries:
        a = etree.SubElement(box, 'a', href='../prototype.html#' + target)
        a.text = title
    button.getparent().replace(button, d)
    return d


