def refine_home(t):
    main = t.find('.//main')
    current = main.xpath('./section')[0]
    remove(current.xpath('./div[h2]')[0])
    current.set('aria-label', 'Current book')
    current.xpath('.//h3')[0].tag='h2'
    main.xpath('./section')[1].set('aria-label', 'Saved books')
    remove(main.xpath('./section')[1].xpath('.//article')[-1])
    txt(find(t, 'Your books', 'h2'), 'Saved books')
    remove(main.xpath('./section')[2])
    for a in main.xpath('.//article'):
        link(a, 'book-saved')
        a.set('aria-label', label(a.xpath('.//span[contains(@class,"font-title-md")]')[0]) + ', book details')
    link(find(t, 'See all', 'button'), 'library-books')
    link(find(t, 'Continue reading', 'button'), 'reader-scroll')
    for e in t.xpath('//*[normalize-space(text())="In library"]'):
        e.text = 'Want to read'
    title=direct(main,"Alice's Adventures")
    if title is not None:txt(title,"Alice's Adventures in Wonderland")
    # Download availability is independent of reading status.
    for article, status in zip(main.xpath('.//a[contains(@class,"group")]'), ['Want to read · Not downloaded', 'Finished · Downloaded']):
        badges = article.xpath('.//span[contains(@class,"inline-flex")]')
        if badges:
            txt(badges[-1], status)
            style(badges[-1], 'font-size:12px;line-height:18px')


def refine_book(t):
    canvas = t.xpath('//main/div[contains(@class,"space-y-6")]')[0]
    hero = canvas.xpath('./section')[0]
    cover = hero.xpath('./div')[0]
    addclass(cover, 'clarity-cover')
    style(cover, 'width:96px;height:144px;margin:0')
    hero.set('style', 'display:flex;flex-direction:row;align-items:center;gap:20px;text-align:left;padding-top:8px')
    meta = hero.xpath('./div')[1]
    style(meta, 'align-items:flex-start;padding:0;flex:1;min-width:0')
    for e in meta.xpath('./h2|./p'):
        style(e, 'text-align:left')
    style(meta.xpath('./h2')[0], 'font-size:24px;line-height:32px;font-weight:500')
    style(meta.xpath('./div')[0], 'justify-content:flex-start;gap:6px;margin-top:12px')
    actions = canvas.xpath('./section')[1]
    txt(actions, '')
    actions.append(fragment('<a class="clarity-primary" href="../prototype.html#book-downloading"><span class="material-symbols-outlined" aria-hidden="true">download</span>Download to read</a>'))
    actions.append(fragment('<a class="clarity-secondary" href="../prototype.html#book-saved"><span class="material-symbols-outlined" aria-hidden="true">library_add</span>Want to read</a>'))
    about = canvas.xpath('./section')[2]
    box = about.xpath('./div')[0]
    txt(box, '')
    box.append(fragment('<p class="clarity-status" style="margin:0">Source: Project Gutenberg · No. 1342</p>'))
    remove(canvas.xpath('./section')[3])
    # Personal controls are defined after saving in the canonical state flow.
    more = t.xpath('//button[@aria-label="More options"]')
    if more:
        remove(more[0].getparent())


def refine_library(t):
    for e in list(t.xpath('//button')):
        if label(e) in ['Sort', 'Explore more books'] or e.get('aria-label') == 'Change layout':
            remove(e)
    for p in t.xpath('//*[normalize-space(text())="Public domain editions via Project Gutenberg"]'):
        remove(p)
    filters = {'All':'library-books','Want to read':'library-want','Reading':'library-reading','Finished':'library-finished','Downloaded':'library-downloaded'}
    for b in list(t.xpath('//button')):
        if label(b) in filters:
            link(b,filters[label(b)])
    remove(t.xpath('//article')[-1])
    txt(direct(t, '4 books'), '3 books')
    routes = ['book-reading', 'book-saved', 'book-downloaded']
    for article, target in zip(t.xpath('//article'), routes):
        button = article.xpath('.//button')[0]
        remove(button)
        a = html.Element('a', {'class': 'clarity-row-link', 'href': '../prototype.html#' + target})
        for child in list(article):
            a.append(child)
        article.append(a)
        link(button, 'library-actions')
        button.set('class', 'clarity-icon')
        article.append(button)
        addclass(a[0], 'clarity-cover')
        for heading in a.xpath('.//h3'):
            addclass(heading, 'clarity-row-title')
        # Preserve progress once, with factual device download state.
        text = label(article)
        for e in a.xpath('.//*[normalize-space(text())="Offline"]'):
            e.text = 'Downloaded'
        for e in a.xpath('.//*[normalize-space(text())="Added 3 days ago"]'):
            e.text = 'Not downloaded'
        for e in a.xpath('.//*[normalize-space(text())="Completed Oct 14"]'):
            e.text = 'Not downloaded'
        for e in a.xpath('.//*[normalize-space(text())="Your rating:"]'):
            remove(e.getparent())
        if "Alice's" in text:
            for e in list(a.xpath('.//*[normalize-space(text())="12% read"]')):
                remove(e.getparent().getparent())
            e=direct(a,'Reading')
            if e is not None:
                txt(e,'Finished')
            p = etree.SubElement(a[1], 'p', {'class':'clarity-status'})
            p.text = 'Downloaded'


def refine_journal(t):
    h = find(t, 'Reading journal', 'h2')
    section = h.getparent().getparent()
    for child in list(section):
        remove(child)
    section.append(fragment('<label class="clarity-field">Book<select aria-label="Journal book" data-journal-book><option value="journal-all">All books</option><option value="journal-book">Pride and Prejudice</option></select></label>'))
    for index, article in enumerate(t.xpath('//article')):
        for button in list(article.xpath('.//button')):
            remove(button)
        a = html.Element('a', {'class':'clarity-journal-link', 'href':'../prototype.html#journal-view'})
        for child in list(article):
            a.append(child)
        article.append(a)
        addclass(a[0], 'clarity-cover')
        # Content remains unabridged; the book and locator provide context.
        for e in a.xpath('.//div[contains(@class,"justify-between")]'):
            style(e, 'flex-wrap:wrap;gap:8px')
        if index == 0:
            a.set('aria-label', 'Open journal entry for ' + label(a.xpath('.//h3')[0]))
        else:
            a.tag='div'
            a.attrib.pop('href',None)
            style(a,'cursor:default')
    new = t.xpath('//button[@aria-label="Create new entry"]')[0]
    link(new, 'journal-book-picker')
    new.set('class', 'clarity-primary')
    addclass(new.getparent(), 'clarity-fab')


def refine_explore(t):
    txt(t.find('.//h1'), 'Explore')
    h = find(t, 'Explore', 'h2')
    if h is not None:
        remove(h.getparent())
    for e in t.xpath('//*[@data-icon="cloud_done"]'):
        remove(e)
    search = t.xpath('//input')[0]
    search.set('type', 'search')
    search.set('enterkeyhint', 'search')
    wrapper=search.getparent()
    filter_button=wrapper.xpath('./button')[0]
    remove(filter_button)
    txt(wrapper,'')
    wrapper.append(fragment('<a href="../prototype.html#explore-search" aria-label="Search books or authors" style="display:flex;align-items:center;gap:12px;flex:1;min-width:0;color:#55483D;font-size:16px;line-height:24px"><span class="material-symbols-outlined" aria-hidden="true">search</span><span>Search books or authors</span></a>'))
    link(filter_button,'explore-filters')
    wrapper.append(filter_button)
    subjects = find(t, 'Browse by subject', 'h3').getparent().getparent()
    txt(subjects, '')
    subjects.set('aria-label', 'Subjects')
    subjects.append(fragment('<div class="clarity-chips">'+''.join('<a href="../prototype.html?subject='+quote(x)+'#explore-results">'+x+'</a>' for x in ['Fiction','Romance','Gothic fiction','Adventure'])+'</div>'))
    txt(find(t, 'Popular classics', 'h3'), 'From the catalogue')
    for button in list(t.xpath('//button[contains(@aria-label,"Save ")]')):
        row = button.getparent()
        meta = row.xpath('./div')[1]
        remove(meta.xpath('./div')[0])
        a = html.Element('a', {'class':'clarity-row-link', 'href':'../prototype.html#book-new'})
        style(a, 'gap:0;align-items:center')
        for child in list(row):
            if child is not button:
                a.append(child)
        row.insert(0, a)
        addclass(a[0], 'clarity-cover')
        title = label(a.xpath('.//h4')[0])
        remove(button)
    for e in t.xpath('//*[contains(text(),"Project Gutenberg & Project Gutenberg")]'):
        if e.tag == 'p':
            txt(e, 'Public domain editions via Project Gutenberg')
    remove(direct(t, 'Designed for quiet offline reading'))


def refine_shelves(t):
    remove(direct(t, 'Your own way to organize a good read.'))
    remove(find(t, 'Your shelves', 'h2'))
    new = find(t, 'New shelf', 'button')
    link(new, 'shelf-create')
    style(new, 'min-height:48px;padding:12px 16px;flex-shrink:0')
    buttons=list(t.xpath('//button[contains(@aria-label,"Shelf options")]'))
    remove(buttons[-1].getparent())
    for index,b in enumerate(buttons[:2]):
        row=b.getparent()
        name='Classics' if index==0 else 'Reading next'
        txt(row.xpath('.//h3')[0],name)
        txt(row.xpath('.//h3/following-sibling::p')[0],'2 books' if index==0 else '1 book')
        b.set('aria-label','Shelf options for '+name)
        stack=row.xpath('./div/div')[0]
        covers=stack.xpath('./div')
        if index==0:
            remove(covers[1])
        else:
            remove(covers[1])
            style(covers[0],'left:0;top:0;transform:none')
    for b in list(t.xpath('//button[contains(@aria-label,"Shelf options")]')):
        row = b.getparent()
        a = row.xpath('./div')[0]
        link(a, 'shelf-detail')
        style(a, 'flex:1;min-width:0;gap:12px')
        addclass(a.xpath('.//h3')[0], 'clarity-shelf-title')
        for d in a.xpath('./div')[0:1]:
            addclass(d, 'clarity-cover')
        menu(b, [('Rename', 'shelf-rename'), ('Delete', 'shelf-delete')])


def refine_welcome(t):
    txt(t.find('.//h1'), 'Read at your own pace')
    remove(direct(t, 'Discover classics, keep your thoughts, and pick up where you left off.'))
    for e in t.xpath('//*[contains(text(),"An account keeps your library")]'):
        if e.tag == 'p':
            txt(e, 'Sign in to sync across devices. Guest reading stays on this device.')
    google = find(t, 'Continue with Google', 'button')
    link(google, 'auth-loading')
    guest = find(t, 'Continue without an account', 'button')
    link(guest, 'home-first')
    txt(guest, 'Continue as guest')
    for a in list(t.xpath('//a[@href="#"]')):
        if 'Privacy' in label(a):
            link(a, 'settings-about')
            txt(a, 'Privacy')
        else:
            remove(a)
    # The MVP has one About/privacy destination, no terms flow.
    for e in t.xpath('//footer//span'):
        remove(e)


def refine_import(t):
    txt(t.find('.//h1'), 'Add guest reading?')
    remove(direct(t, 'Add the reading you saved on this device to your personal account.'))
    summary = t.xpath('//section[@aria-labelledby="device-summary-label"]')[0]
    txt(summary, '')
    summary.append(fragment('<p class="clarity-label" id="device-summary-label">Guest reading on this device</p><div class="clarity-chips" style="margin-top:12px"><span>3 books</span><span>1 journal entry</span><span>1 highlight</span><span>2 shelves</span></div>'))
    preview = find(t, 'Local books preview')
    if preview is not None:
        box = preview.getparent().getparent()
        txt(box, '')
        box.append(fragment('<p class="clarity-label">Already in this account</p><p style="font-size:16px;line-height:24px;margin-top:8px">Pride and Prejudice<br>Frankenstein<br>Alice’s Adventures in Wonderland</p><p class="clarity-status">0 new books · 3 already saved</p>'))
    for e in t.xpath('//p'):
        value = label(e)
        if value.startswith('2 books are already'):
            txt(e, 'Books already saved are not added twice.')
        elif value.startswith('Your notes, highlights'):
            txt(e, 'Your journal, highlights, shelves, and reading positions are kept.')
        elif value.startswith('Your device library will be combined'):
            remove(e)
        elif value.startswith('Your device library stays'):
            txt(e, 'Keeping them separate leaves guest reading available on this device.')
    add = find(t, 'Add and sync', 'button')
    txt(add, 'Add to account')
